  ('leo_travel', 'msg_g2_02_1', 'tv_g2_02', 'cdp_g2_02', 'persona_travel_joy_v1', 'tp_g2_02', 'webchat', 'active', 'user', 'Cả nhà đi Sa Pa vẫn theo kế hoạch cũ, các con ít khi được chọn hoạt động.', ARRAY['du lịch','lịch trình']::text[], '2025-12-19T20:00:00+07:00', 'travel_planning', 0.8, '2025-12-19T20:00:00+07:00'),
  ('leo_travel', 'msg_g2_02_2', 'tv_g2_02', 'cdp_g2_02', 'persona_travel_joy_v1', 'tp_g2_02', 'webchat', 'active', 'user', 'Năm nay tôi muốn cả nhà cùng làm một việc mới, không chỉ ngồi nghỉ.', ARRAY['du lịch','lịch trình']::text[], '2026-09-14T20:00:00+07:00', 'travel_planning', 0.8, '2026-09-14T20:00:00+07:00'),
  ('leo_travel', 'msg_g2_03_1', 'tv_g2_03', 'cdp_g2_03', 'persona_travel_joy_v1', NULL, 'zalo', 'active', 'user', 'Tôi làm việc ở một quán cà phê quen mỗi tuần, chuyến đi cũng chỉ là đổi quán.', ARRAY['du lịch','lịch trình']::text[], '2025-10-29T20:00:00+07:00', 'travel_planning', 0.8, '2025-10-29T20:00:00+07:00'),
  ('leo_travel', 'msg_g2_03_2', 'tv_g2_03', 'cdp_g2_03', 'persona_travel_joy_v1', NULL, 'zalo', 'active', 'user', 'Tôi muốn một chuyến đi có người mới và vài trải nghiệm đáng nhớ.', ARRAY['du lịch','lịch trình']::text[], '2026-08-04T20:00:00+07:00', 'travel_planning', 0.8, '2026-08-04T20:00:00+07:00'),
  ('leo_travel', 'msg_g3_01_1', 'tv_g3_01', 'cdp_g3_01', 'persona_travel_joy_v1', 'tp_g3_01', 'zalo', 'active', 'user', 'Cả nhóm bạn lần nào đi Hạ Long cũng tự làm việc riêng, ít khi đi chung.', ARRAY['du lịch','lịch trình']::text[], '2025-12-09T20:00:00+07:00', 'travel_planning', 0.8, '2025-12-09T20:00:00+07:00'),
  ('leo_travel', 'msg_g3_01_2', 'tv_g3_01', 'cdp_g3_01', 'persona_travel_joy_v1', 'tp_g3_01', 'zalo', 'active', 'user', 'Lần tới tôi muốn cùng làm một hoạt động chung và chụp vài khoảnh khắc đẹp.', ARRAY['du lịch','lịch trình']::text[], '2026-09-09T20:00:00+07:00', 'travel_planning', 0.8, '2026-09-09T20:00:00+07:00'),
  ('leo_travel', 'msg_g3_02_1', 'tv_g3_02', 'cdp_g3_02', 'persona_travel_joy_v1', 'tp_g3_02', 'webchat', 'active', 'user', 'Chuyến Huế tháng trước tôi ghi nhầm một chuyến hai lần, nhờ sửa giúp.', ARRAY['du lịch','lịch trình']::text[], '2025-11-14T20:00:00+07:00', 'travel_planning', 0.8, '2025-11-14T20:00:00+07:00'),
  ('leo_travel', 'msg_g3_02_2', 'tv_g3_02', 'cdp_g3_02', 'persona_travel_joy_v1', 'tp_g3_02', 'webchat', 'active', 'user', 'Tôi muốn chuyến tới đi với bạn bè, ngân sách vừa phải và có nhiều điều mới.', ARRAY['du lịch','lịch trình']::text[], '2026-10-01T20:00:00+07:00', 'travel_planning', 0.8, '2026-10-01T20:00:00+07:00'),
  ('leo_travel', 'msg_g3_03_1', 'tv_g3_03', 'cdp_g3_03', 'persona_travel_joy_v1', NULL, 'webchat', 'active', 'user', 'Chuyến đi nào lịch cũng kín từ sáng đến tối, tôi chỉ muốn ít việc hơn.', ARRAY['du lịch','lịch trình']::text[], '2025-11-27T20:00:00+07:00', 'travel_planning', 0.8, '2025-11-27T20:00:00+07:00'),
  ('leo_travel', 'msg_g3_03_2', 'tv_g3_03', 'cdp_g3_03', 'persona_travel_joy_v1', NULL, 'webchat', 'active', 'user', 'Lần sau tôi muốn đi ít điểm hơn, nhưng có một hoạt động nhóm nho nhỏ.', ARRAY['du lịch','lịch trình']::text[], '2026-09-27T20:00:00+07:00', 'travel_planning', 0.8, '2026-09-27T20:00:00+07:00');
