INSERT INTO knowledge_chunks (id, tenant_id, source_id, content, embedding, chunk_sequence, metadata, created_at)
VALUES
  ('9ca7ddca-e2fe-5ba7-9afb-0e8b112cb51c', 'leo_travel', '60f47ce8-3f14-58fa-90a5-03d89b89ed23', 'Trí nhớ về chuyến đi thường bám vào vài khoảnh khắc khác thường hơn là lịch trình đều đặn. Một việc nhỏ ngoài dự kiến có thể tạo khác biệt.', seed_vec768('kc:bat_ngo:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('a80a40b8-9f9f-57c1-acf5-c2e8c85a8297', 'leo_travel', '60f47ce8-3f14-58fa-90a5-03d89b89ed23', 'Điều bất ngờ nên đủ nhỏ để không làm mất cảm giác an toàn. Chọn một khung giờ trống và để người đi cùng quyết định hoạt động.', seed_vec768('kc:bat_ngo:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('f98fb481-9368-5c41-9360-a9d5fc82af27', 'leo_travel', '011d03db-fa04-502a-829a-48b01a939bf9', 'Nhiều người sinh giai đoạn này đã quen với chuyến đi theo kế hoạch cứng. Khi đổi sang nhịp chậm, nên giữ một hoạt động quen và thêm một điểm mới.', seed_vec768('kc:g1:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('84ca4b23-2a56-5929-8fdf-9f1d36037a2c', 'leo_travel', '011d03db-fa04-502a-829a-48b01a939bf9', 'Với chuyến đi gia đình, nên để một buổi sáng không có lịch. Thời gian trống giúp mọi người trò chuyện nhiều hơn.', seed_vec768('kc:g1:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('58949241-e84c-50c8-ab82-bb1dd65c668d', 'leo_travel', '0045c29e-0603-5863-a684-a71f9d5345e0', 'Chuyến đi cuối tuần thường lặp lại một địa điểm quen. Thử đổi một yếu tố mỗi chuyến: món ăn, tuyến đường hoặc cách di chuyển.', seed_vec768('kc:g2:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('4c6df744-a983-50f7-9fd2-05d7daffc118', 'leo_travel', '0045c29e-0603-5863-a684-a71f9d5345e0', 'Ghi chú ngắn sau mỗi chuyến, như ba điều đã thấy và một điều muốn thử lần sau, giúp nhìn lại trải nghiệm rõ hơn.', seed_vec768('kc:g2:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('14ce6d84-1f04-581d-a44f-dee5b65aae6d', 'leo_travel', 'aa715234-ef8c-584b-b47e-acbc3fec4e83', 'Đi cùng bạn bè vẫn dễ thành mỗi người một việc. Một hoạt động chung như nấu ăn hoặc đi bộ phố cũ giúp nhóm gắn kết hơn.', seed_vec768('kc:g3:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('aa54e7ea-3c1f-51d0-8eb9-3973ee72a3c7', 'leo_travel', 'aa715234-ef8c-584b-b47e-acbc3fec4e83', 'Ngân sách vừa phải không đồng nghĩa với ít trải nghiệm. Chọn một trải nghiệm đáng tiền mỗi chuyến và tiết kiệm phần còn lại.', seed_vec768('kc:g3:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('1b6f6bf2-eaf5-5164-9907-7ec31e166f0b', 'leo_travel', '63bfc173-69f6-5b0d-89b3-9b7ca7b33667', 'Buổi sáng ở hồ Xuân Hương thường yên tĩnh hơn. Nên đến sớm để đi bộ quanh hồ trước khi đông khách.', seed_vec768('kc:dalat:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('9f90f3cc-6e11-58fb-9c49-066082c64835', 'leo_travel', '63bfc173-69f6-5b0d-89b3-9b7ca7b33667', 'Buổi chiều trên đồi chè hợp với nhịp chậm. Chỉ nên chọn hai điểm trong một buổi để không mệt.', seed_vec768('kc:dalat:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('34dacc94-2519-5115-8083-bfea9a4117aa', 'leo_travel', '60a1100d-a79b-5fb6-a825-7db720642fec', 'Phố cổ đẹp nhất khi đèn lồng lên. Nên đi bộ không cần đích đến và thử một món địa phương mỗi tối.', seed_vec768('kc:hoian:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('3d521f0f-1862-5446-a4ed-cd71f6467a74', 'leo_travel', '60a1100d-a79b-5fb6-a825-7db720642fec', 'Đi thuyền trên sông Hoài buổi tối phù hợp với nhóm nhỏ, giúp trò chuyện nhiều hơn.', seed_vec768('kc:hoian:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('167026c7-2552-531b-bdec-9ab850b650f0', 'leo_travel', 'aa69cc95-4c29-5d5e-ab6b-d2265c3879e2', 'Chuyến tàu nửa ngày đủ để ngắm vịnh mà không mất nhiều thời gian. Chọn khoang ngoài trời để có nhiều khoảnh khắc đẹp.', seed_vec768('kc:halong:1'), 1, '{"muc": 1}'::jsonb, '2026-01-10T09:00:00+07:00'),
  ('1d5f1126-6b48-523d-b287-d9577cb83d94', 'leo_travel', 'aa69cc95-4c29-5d5e-ab6b-d2265c3879e2', 'Người đi lần đầu nên chọn chuyến có hướng dẫn viên để hiểu thêm về các địa danh trên vịnh.', seed_vec768('kc:halong:2'), 2, '{"muc": 2}'::jsonb, '2026-01-10T09:00:00+07:00');
