  ('64eba248-0368-5109-b679-0ccb3d9bb206', 'leo_travel', 'travel', 1, 'active', '[{"idx": 0, "code": "NV", "name": "novelty", "definition": "Số trải nghiệm mới trong 90 ngày (điểm, món, hoạt động)", "unit": "0..1", "normalization": "chuyến và điểm mới quy về 0..1", "direction": "higher_is_closer", "requires_consent_scope": "data_source:booking_history"}, {"idx": 1, "code": "SC", "name": "social", "definition": "Kết nối có ý nghĩa với người đồng hành", "unit": "0..1", "normalization": "khảo sát hoặc tin nhắn, kẹp 0..1", "direction": "higher_is_closer", "requires_consent_scope": "data_source:chat_text"}, {"idx": 2, "code": "PF", "name": "pace_fit", "definition": "Mức phù hợp nhịp độ (số điểm mỗi ngày)", "unit": "0..1", "normalization": "điểm mỗi ngày / 6, kẹp 0..1", "direction": "in_range_is_best", "requires_consent_scope": "journey:travel_joy"}, {"idx": 3, "code": "MM", "name": "memorable", "definition": "Mức ghi nhận khoảnh khắc đáng nhớ sau chuyến đi", "unit": "0..1", "normalization": "khoảnh khắc ghi lại / 5, kẹp 0..1", "direction": "higher_is_closer", "requires_consent_scope": "data_source:chat_text"}]'::jsonb, '{"metric": "weighted_euclidean_to_range", "weights_from": "goal.dim_mask", "d_max": 1.0}'::jsonb, 'Persona du lịch: từ nhàm chán sang vui hơn. Chiều PF là khoảng mục tiêu, quá dày và quá thưa đều lệch.');
